\label{lem1}  \cite{kittaneh1992arithmetic}
  Let $T, S \in B_p(H)$ be such that TS is self-adjoint, and let $1\leq p\leq \infty$. Then
$\|TS\|_p \leq \|\Re(ST)\|_p$.

\label{cv1}\cite{Be2021on}
Let $T\in \mathsf{B}_p(\mathsf{H})$ be such that $T^2 = 0$. Then
\[w(T)=2^{\frac{1}{p}-1}\|T\|_p.\]

\label{1e1}
 For $1 \leq p\leq \infty$, $t \in [0,1]$ and $T \in B_p(H)$,  if $f,g$ are non-negative continuous functions on $[0,\infty)$ such that $f(x)g(x)=x$, then 
we have  
\begin{align}\label{0c1}
w_{t,p}(T)\leq2^{\frac1p}t\left[
w_p(\widetilde{T}_{f,g})
+
\frac{1}{2}
\left\|
f^2(|T|)+g^2(|T|)
\right\|_p\right]+|1-2t|\|T\|_p.
\end{align}

\label{e1}
 For $1 \leq p\leq \infty$, $\mathsf{s},t \in [0,1]$ and $T \in B_p(H)$, we have  
\begin{align}\label{c0}
w_{t,p}(T)\leq2^{\frac1p}t\left[
w_p(\widetilde{T}_{1-\mathsf{s}})
+
\frac{1}{2}
\left\|
|T|^{2\mathsf{s}}+|T|^{2(1-\mathsf{s})}
\right\|_p\right]+|1-2t|\|T\|_p.
\end{align}

\label{co1}
Let $T\in B_p(H)$ and $1\le p\le\infty$. For $\mathsf{s}=\frac{1}{2}$ in \eqref{c0}, we get
\begin{align}
 w_{t,p}(T)\leq 2^\frac{1}{p}t\left[
w_p(\widetilde{T})
+
\left\|T
\right\|_p\right]+|1-2t|\|T\|_p.
\end{align}

For $T \in B(H)$ and $\mathsf{s}, t \in [0,1]$, we get  
\begin{align}\label{c010}
w_t(T)\leq t
\left[w(\widetilde{T}_{1-\mathsf{s}})
+
\frac{1}{2}
\left\|
|T|^{2\mathsf{s}}+|T|^{2(1-\mathsf{s})}
\right\|\right]+|1-2t|\|T\|.
\end{align}

For $1 \leq p\leq \infty$, $\mathsf{s},t \in [0,1]$ and $T \in B_p(H)$, we have
\begin{align}\label{c1}
w_{t,p}(T)\leq2^{\frac1p}t
\left[\min_{0\le \mathsf{s}\le 1}
w_p(\widetilde{T}_{1-\mathsf{s}})
+\frac{1}{2}
\left\|
|T|^{2\mathsf{s}}+|T|^{2(1-\mathsf{s})}
\right\|_p\right]+|1-2t|\|T\|_p.
\end{align}

For $1 \leq p\leq \infty$, $\mathsf{s} \in [0,1]$ and $T \in B_p(H)$, we get
\begin{align}
w_{p}(T)\leq2^{\frac{1}{p}-1}
\min_{0\le \mathsf{s}\le 1}
w_p(\widetilde{T}_{1-\mathsf{s}})
+
2^{\frac1p-2}
\left\||T|^{2\mathsf{s}}+
|T|^{2(1-\mathsf{s})}
\right\|_p.    
\end{align}

For $T\in B(H)$ and $\mathsf{s},t \in [0,1]$, we obtain
\begin{align}\label{c2}
w_t(T)
\le
t\left[\min_{0\le \mathsf{s}\le 1}
w(\widetilde{T}_{1-\mathsf{s}})
+
\frac{1}{2}
\left\|
|T|^{2\mathsf{s}}+|T|^{2(1-\mathsf{s})}
\right\|\right]+|1-2t|\|T\|.
\end{align}

For $T\in B(H)$ and $\mathsf{s} \in [0,1]$, we get
\begin{align}\label{c3}
w(T)
\le
\frac{1}{2}
w(\widetilde{T}_{1-\mathsf{s}})
+
\frac{1}{4}
\left\|
|T|^{2(1-\mathsf{s})}+|T|^{2\mathsf{s}}
\right\|.    
\end{align}

\label{t11}
 For $1 \leq p\leq \infty$, $\mathsf{s},t \in [0,1]$ and $T \in B_p(H)$, we have
\begin{align}\label{t5}
w_{t,2p}^2(T)
\le
(1-2t+2t^2) \|T\|_{p}
\|\widetilde{T}_\mathsf{s}\|
+
t(1-t)\|T^*T+TT^*\|_{p}.
\end{align}

Let \(T=U|T|\) be the polar decomposition of \(T\), and let
\(\theta\in\mathbb{R}\).
Consider, $g(x)=x^{1-\mathsf{s}}$ and $f(x)=x^\mathsf{s}$ in \eqref{1w0}, we have
\begin{align}
\nonumber (\Re_t(e^{i\theta}T))^2
&\leq
 t^2e^{2i\theta}U|T|^{1-\mathsf{s}}\Tilde{T}_\mathsf{s}|T|^\mathsf{s} + (1-t)^2e^{-2i\theta}|T|^\mathsf{s}(\Tilde{T}_\mathsf{s})^*|T|^{1-\mathsf{s}}U^* 
\\\nonumber &\hspace{5cm}+ t(1-t)(T^*T + TT^*).
\end{align}
Thus,
\begin{align*}
\left\|
\bigl(\Re_t(e^{i\theta}T)\bigr)^2\right\|_{p}
&\le
t^2\left\|
U|T|^{1-\mathsf{s}}\widetilde{T}_\mathsf{s}|T|^\mathsf{s}
\right\|_{p}
+
(1-t)^2\left\|
|T|^\mathsf{s}(\widetilde{T}_\mathsf{s})^*|T|^{1-\mathsf{s}}U^*
\right\|_{p}\\
&\hspace{2cm}+
t(1-t)\|T^*T+TT^*\|_{p}\\
&\le
t^2\left\|
|T|^{1-\mathsf{s}}\widetilde{T}_\mathsf{s}|T|^\mathsf{s}
\right\|_{p}
+
(1-t)^2\left\|
|T|^\mathsf{s}(\widetilde{T}_\mathsf{s})^*|T|^{1-\mathsf{s}}
\right\|_{p}\\
&\hspace{2cm}+
t(1-t)\|T^*T+TT^*\|_{p}
\qquad
\text{(by \eqref{2})}\\
&\le
t^2\Big\||T|\widetilde{T}_\mathsf{s}\Big\|_{p}^{\,1-\mathsf{s}}
\,
\Big\|\widetilde{T}_\mathsf{s}|T|\Big\|_{p}^{\,\mathsf{s}}
+
(1-t)^2\Big\||T|(\widetilde{T}_\mathsf{s})^*\Big\|_{p}^{\,\mathsf{s}}
\,
\Big\|(\widetilde{T}_\mathsf{s})^*|T|\Big\|_{p}^{\,1-\mathsf{s}}\\
&\hspace{2cm}+
t(1-t)
\|T^*T+TT^*\|_{p}
\qquad\qquad
\text{(by Lemma \ref{l3})}\\
&\le
\{t^2+(1-t)^2\}
\|T\|_{p}
\|\widetilde{T}_\mathsf{s}\|+
t(1-t)
\|T^*T+TT^*\|_{p}
\qquad
\text{(by \eqref{2}}\\
&=
(1-2t+2t^2)
\|T\|_{p}
\|\widetilde{T}_\mathsf{s}\|+
t(1-t)
\|T^*T+TT^*\|_{p}.
\end{align*}
By taking the supremum in the above inequality over
\(\theta\in\mathbb{R}\) and use \eqref{w0}, we get 
\begin{align*}
w_{t,2p}^2(T)
\le
(1-2t+2t^2) \|T\|_{p}
\|\widetilde{T}_\mathsf{s}\|
+
t(1-t)\|T^*T+TT^*\|_{p}.
\end{align*}

For $1 \leq p\leq \infty$, $t \in [0,1]$ and $T \in B_p(H)$, we get
    \begin{align}\label{qe3}
w_{t,2p}^2(T)
\le
(1-2t+2t^2) \|T\|_{p}
\|\widetilde{T}\|
+
t(1-t)\|T^*T+TT^*\|_{p}.
\end{align}
If we take \(\widetilde{T}=0\) in \eqref{qe3}, then we get the following results.
\begin{corollary}
For $T\in B_p(T)$,
$ w_{t,2p}^2(T)
\le
t(1-t)
\|T^*T+TT^*\|_{p}$.   
\end{corollary}







\noindent For $t=\frac{1}{2}$ in \eqref{qe3}, we have
\begin{align}\label{t09}
w_{2p}^2(T)
\le
\frac{1}{2} \|T\|_{p}
\|\widetilde{T}\|
+
\frac{1}{4}\|T^*T+TT^*\|_{p}.
\end{align}

For $1 \leq p\leq \infty$, $\mathsf{s},t \in [0,1]$ and $T \in B_p(H)$, we have
\begin{align}\label{c022}
w_{t,2p}^2(T)
\le
(1-2t+2t^2) \|T\|_{p}
\min_{0\le \mathsf{s}\le1}\|\widetilde{T}_\mathsf{s}\|
+
t(1-t)\|T^*T+TT^*\|_{p}.
\end{align}

From Theorem \ref{t11}, we have
\begin{align*}
w_{t,2p}^2(T)&\leq (1-2t+2t^2)
\|T\|_{p}
\|\widetilde{T}_\mathsf{s}\|+
t(1-t)
\||T|^2+|T^*|^2\|_{p}\\
&\leq (1-2t+2t^2)
\|T\|_{p}
\|\widetilde{T}_\mathsf{s}\|\\
&\hspace{2cm}+
t(1-t)
\left(
\left(\||T|^2\|_{p}^p
+\||T^{*}|^2\|_{p}^p\right)^{1/p}
+2^{1/p}\big\||T||T^*|\big\|_{p}
\right)\\
&\hspace{6cm} (\text{using the Lemma \ref{lt1}})\\
&\leq (1-2t+2t^2)
\|T\|_{p}
\min_{0\le \mathsf{s}\le1}\big\|\widetilde{T}_\mathsf{s}\big\|+2^\frac{1}{p}t(1-t)\big(\|T\|^2_p+\|T^2\|_{p}\big).
\end{align*}

For $1 \leq p\leq \infty$, $\mathsf{s} \in [0,1]$ and $T \in B_p(H)$, we get
\begin{align}\label{c023}
w_{2p}^2(T)
\le
\frac{1}{2} \|T\|_{p}
\min_{0\le \mathsf{s}\le1}\|\widetilde{T}_\mathsf{s}\|
+
\frac{1}{4}\|T^*T+TT^*\|_{p}.
\end{align}

For $T \in B(H)$ and $\mathsf{s}, t\in [0,1]$, we have 
\begin{align}\label{f1}
w_t^2(T) \leq (1-2t+2t^2)\|T\|\|\widetilde{T}_\mathsf{s}\| + t(1-t)\|T^*T + TT^*\|.
\end{align}

Let $T\in B(H)$. For $p=\infty$, the Schatten $p$-norm coincides with the usual operator (spectral) norm. That is,
\[
\|T\|_{\infty}=\|T\|
=\sup_{\|x\|=1}\|Tx\|
=\sigma_{\max}(T)
=\sqrt{\lambda_{\max}(T^{*}T)},
\]
where $\sigma_{\max}(T)$ denotes the largest singular value of $T$, and $\lambda_{\max}(T^{*}T)$ is the largest eigenvalue of the positive operator $T^{*}T$. \\
