\label{te4}
For $1 \leq p\leq \infty$, $\mathsf{s},t \in [0,1]$ and $T \in B_p(H)$, we have
 \begin{align*}
w_{t,4p}^4(T) &\leq \{t^2+(1-t)^2\}\|T\|^2_{2p}\|\widetilde{T}_\mathsf{s}\|^2_{2p} \\
&\qquad
+
t^2\left\|
T^2K+KT^2
\right\|_{p}+(1-t)^2\left\|(T^*)^2K+K(T^*)^2\right\|_{p}
+\|K\|^2_{2p},
\end{align*}
where $K=T^*T+TT^*$.

For $1 \leq p\leq \infty$, $\mathsf{s},t \in [0,1]$ and $T \in B_p(H)$, we have
\begin{align*}
w_{t,p}(T+S)\leq &2^{\frac1p}t
\left[
w_p(\widetilde{T}_{1-\mathsf{s}})+
w_p(\widetilde{S}_{1-\mathsf{s}})\right]+|1-2t|[\|T\|_p+\|S\|_p]\\
&+2^{\frac1p-1}t\left[
\left\|
|T|^{2\mathsf{s}}+|T|^{2(1-\mathsf{s})}
\right\|_p+\left\|
|S|^{2\mathsf{s}}+|S|^{2(1-\mathsf{s})}
\right\|_p\right].
\end{align*}

For $1 \leq p\leq \infty$, $\mathsf{s} \in [0,1]$ and $T, S \in B_p(H)$, we have
\begin{align*}
w_{p}(T+S)\leq &2^{\frac1p-1}
\left[
w_p(\widetilde{T}_{1-\mathsf{s}})+
w_p(\widetilde{S}_{1-\mathsf{s}})\right]\\
&+2^{\frac1p-2}\left[
\left\|
|T|^{2\mathsf{s}}+|T|^{2(1-\mathsf{s})}
\right\|_p+\left\|
|S|^{2\mathsf{s}}+|S|^{2(1-\mathsf{s})}
\right\|_p\right].
\end{align*}  
Moreover, for $\mathsf{s=\frac{1}{2}}$, 
\begin{align*}
w_{p}(T+S)\leq &2^{\frac1p-1}
\left[
w_p(\widetilde{T})+
w_p(\widetilde{S})\right]+2^{\frac1p-1}[\|T\|_p+\|S\|_p].
\end{align*}

For $T, S \in B(H)$ and $\mathsf{s},t \in [0,1]$, we have
\begin{align*}
w_t(T+S)\leq & t
\left[
w(\widetilde{T}_{1-\mathsf{s}})+
w(\widetilde{S}_{1-\mathsf{s}})\right]+|1-2t|[\|T\|+\|S\|]\\
&+\frac{1}{2}t\left[
\left\|
|T|^{2\mathsf{s}}+|T|^{2(1-\mathsf{s})}
\right\|+\left\|
|S|^{2\mathsf{s}}+|S|^{2(1-\mathsf{s})}
\right\|\right].
\end{align*}  
Moreover, for $\mathsf{s=\frac{1}{2}}$, 
\begin{align*}
w_t(T+S)\leq t
\left[
w(\widetilde{T})+
w(\widetilde{S})\right]+\{|1-2t|+t\}[\|T\|+\|S\|].\\
\end{align*}
